using System.Collections.Generic;
using Artillery.Core.Match;
using Godot;

namespace Artillery.Game.Audio;

/// <summary>
/// Autoload singleton (registered as <c>Audio</c> in project.godot). Plays sound cues from a pool of
/// AudioStreamPlayers and crossfades looped music. Files are generated by tools/sfx/gen-sfx.js.
/// Missing files are skipped silently.
/// </summary>
public partial class AudioManager : Node
{
    /// <summary>
    /// SoundId -> file under res://audio/sfx/. File name is snake_case of the enum name
    /// (e.g. ExplosionBig -> explosion_big.wav), as written by tools/sfx/gen-sfx.js.
    /// </summary>
    public static readonly IReadOnlyDictionary<SoundId, string> SoundFiles = new Dictionary<SoundId, string>
    {
        [SoundId.GooSplat] = "goo_splat.wav",
        [SoundId.LaunchHeavy] = "launch_heavy.wav",
        [SoundId.AirStrike] = "air_strike.wav",
        [SoundId.LaunchLight] = "launch_light.wav",
        [SoundId.ExplosionNuke] = "explosion_nuke.wav",
        [SoundId.ExplosionMedium] = "explosion_medium.wav",
        [SoundId.Countdown] = "countdown.wav",
        [SoundId.Shockwave] = "shockwave.wav",
        [SoundId.Victory] = "victory.wav",
        [SoundId.ExplosionBig] = "explosion_big.wav",
        [SoundId.ExplosionSmall] = "explosion_small.wav",
        [SoundId.ShieldBreak] = "shield_break.wav",
        [SoundId.Splash] = "splash.wav",
        [SoundId.Rumble] = "rumble.wav",
        [SoundId.AirStrikePlane] = "air_strike_plane.wav",
        [SoundId.Teleport] = "teleport.wav",
        [SoundId.Fire] = "fire.wav",
        [SoundId.Scatter] = "scatter.wav",
        [SoundId.UiClick] = "ui_click.wav",
        [SoundId.Button] = "button.wav",
        [SoundId.ExplosionHuge] = "explosion_huge.wav",
        [SoundId.Launch] = "launch.wav",
        [SoundId.TimeUp] = "time_up.wav",
        [SoundId.Menu] = "menu.wav",
        [SoundId.Credits] = "credits.wav",
    };

    private const int PoolSize = 8;
    private const float PitchJitter = 0.05f;      // +/- 5% random pitch per cue
    private const float CrossfadeSeconds = 1.5f;
    private const float SilentDb = -60f;

    private static AudioManager? _instance;
    private static float _masterVolume = 1f;

    private readonly List<AudioStreamPlayer> _pool = new();
    private readonly AudioStreamPlayer[] _music = new AudioStreamPlayer[2];
    private readonly Tween?[] _fades = new Tween?[2];
    private readonly Dictionary<string, AudioStream?> _cache = new();
    private int _poolNext;
    private int _musicActive;
    private string? _musicName;

    /// <summary>Master bus volume, 0..1 (linear; applied to the Master bus in dB).</summary>
    public static float MasterVolume
    {
        get => _masterVolume;
        set
        {
            _masterVolume = Mathf.Clamp(value, 0f, 1f);
            // Master bus is index 0.
            AudioServer.SetBusVolumeDb(0, _masterVolume <= 0.001f ? -80f : Mathf.LinearToDb(_masterVolume));
        }
    }

    public override void _Ready()
    {
        _instance = this;
        for (int i = 0; i < PoolSize; i++)
        {
            var p = new AudioStreamPlayer { Bus = "Master" };
            AddChild(p);
            _pool.Add(p);
        }
        for (int i = 0; i < _music.Length; i++)
        {
            _music[i] = new AudioStreamPlayer { Bus = "Master", VolumeDb = SilentDb };
            AddChild(_music[i]);
        }
        MasterVolume = _masterVolume;
    }

    public override void _ExitTree()
    {
        if (_instance == this) _instance = null;
    }

    /// <summary>Plays a sound cue on the next free pooled player (the oldest is reused if all are busy).</summary>
    public static void Play(SoundId id) => _instance?.PlayCue(id);

    /// <summary>Crossfades to res://audio/music/&lt;name&gt;.wav (looped). No-op if it is already the current track.</summary>
    public static void PlayMusic(string name) => _instance?.StartMusic(name);

    /// <summary>Fades out the current music.</summary>
    public static void StopMusic() => _instance?.FadeOutAll();

    private void PlayCue(SoundId id)
    {
        if (id == SoundId.None || !SoundFiles.TryGetValue(id, out var file)) return;
        AudioStream? stream = Load("res://audio/sfx/" + file);
        if (stream == null) return;

        AudioStreamPlayer player = _pool.Find(p => !p.Playing) ?? _pool[_poolNext++ % PoolSize];
        player.Stream = stream;
        player.PitchScale = 1f + (float)GD.RandRange(-PitchJitter, PitchJitter);
        player.Play();
    }

    private void StartMusic(string name)
    {
        if (name == _musicName) return;
        _musicName = name;

        AudioStream? stream = Load($"res://audio/music/{name}.wav");
        if (stream is AudioStreamWav wav) wav.LoopMode = AudioStreamWav.LoopModeEnum.Forward;

        int outgoing = _musicActive;
        int incoming = 1 - _musicActive;
        _musicActive = incoming;

        AudioStreamPlayer inPlayer = _music[incoming];
        inPlayer.Stream = stream;
        inPlayer.VolumeDb = SilentDb;
        if (stream != null) inPlayer.Play();
        Fade(incoming, 0f, stopAfter: false);
        Fade(outgoing, SilentDb, stopAfter: true);
    }

    private void FadeOutAll()
    {
        _musicName = null;
        for (int i = 0; i < _music.Length; i++)
            if (_music[i].Playing) Fade(i, SilentDb, stopAfter: true);
    }

    private void Fade(int slot, float targetDb, bool stopAfter)
    {
        _fades[slot]?.Kill();
        Tween tween = CreateTween();
        tween.TweenProperty(_music[slot], "volume_db", targetDb, CrossfadeSeconds);
        if (stopAfter) tween.TweenCallback(Callable.From(_music[slot].Stop));
        _fades[slot] = tween;
    }

    /// <summary>Loads a stream once and caches it. Returns null (silently) if the file does not exist.</summary>
    private AudioStream? Load(string path)
    {
        if (_cache.TryGetValue(path, out var cached)) return cached;
        AudioStream? stream = ResourceLoader.Exists(path) ? ResourceLoader.Load<AudioStream>(path) : null;
        _cache[path] = stream;
        return stream;
    }
}
